import { ControlModelsManager } from '../logic/control-models-manager';
import { FormDomManager } from './form-dom-manager';
export class DragAndDropManager {
    private adjustment: { left: number, top: number };
    constructor(private $: JQueryStatic, private domManager: FormDomManager,
        private modelManager: ControlModelsManager) {
            this.setUp();
    }

    private setUp(): void { // todo public or call on constructor;

        this.$('.toolbox-fields')
            .sortable({
                group: 'connect-area',
                handle: 'i.drag-handle',
                itemSelector: '.neo-control',
                containerSelector: '.sortable-container',
                drop: false,
                onDrop: ($item: JQuery<HTMLElement>, container, _super, event) => {
                    const control = this.modelManager.grabDroppedControlModel(this.domManager.getControlId($item),
                        this.domManager.getParentId($item));
                    this.domManager.setControlId($item, control.ControlId);
                    _super($item, container);
                },
                onDragStart: ($item: JQuery<HTMLElement>, container, _super) => {
                    if (container.options.clone)
                        $item.clone(true, true).insertAfter($item);

                    var offset = $item.offset();
                    var pointer = container.rootGroup.pointer;

                    this.adjustment = {
                        left: pointer.left - offset.left,
                        top: pointer.top - offset.top
                    };

                    _super($item, container);
                },
                onDrag: ($item: JQuery<HTMLElement>, position) => {
                    $item.css({
                        left: position.left - this.adjustment.left,
                        top: position.top - this.adjustment.top
                    });
                }
            });

        this.$('.toolbox-controls')
            .sortable({
                group: 'connect-area',
                drop: false,
                clone: true
            });

        this.$('.form-element')
            .sortable({
                group: 'connect-area'
            });
    }
}