import { ControlModel } from '../models/form-models/control-model';
import { ControlType } from "../models/form-models/control-type";
import { PropertyType } from '../models/form-models/property-type';
import { IUtility } from '../utils/iutility';
import { PropertyValueType } from '../models/form-models/property-value-type';

export class ControlModelsManager {
    private newlyAddedSuffix: number = 0;
    constructor(private controlModels: ControlModel[],
        private readonly propertyTypes: PropertyType[],
        private getControlTypes: () => ControlType[],
        private readonly utils: IUtility,
        private readonly isFilter: boolean,
        private readonly isColumnSettings: boolean) {

    }
    public obtainAlternativeControls(control: ControlModel): ControlType[] {
        const result = [];
        if ((control.ControlGroups || []).length === 0) {
            return result;
        }
        const controlTypes = this.getControlTypes();
        for (var i = 0; i < controlTypes.length; i++) {
            if (controlTypes[i].ControlGroups === null) {
                continue;
            }
            if ((this.controlIsInGroup(control, 'ContainerItem') || this.controlIsInGroup(control, 'ContainerGroup'))
                && controlTypes[i].Id === 'FieldSet') {
                result.push(controlTypes[i]);
            } else if (controlTypes[i].ControlGroups.every(item => {
                if (control.ControlGroups.indexOf(item) === -1)
                    return false;
                if (item === 'ContainerItem' && control.ParentControlId === null)
                    return false;
                return true;
            })) {
                result.push(controlTypes[i]);
            }
        }
        return result;
    };
    public getRelevantPropertyTypes(control: ControlModel): { [key: string]: PropertyType } {
        const propertyTypesObj = this.getPropertyTypes();
        return Object.keys(propertyTypesObj)
            .filter(ptId => this.propertyIsRelevant(control, ptId))
            .reduce((obj, key) => {
                return {
                    ...obj,
                    [key]: propertyTypesObj[key]
                };
            }, {});
    }
    public grabDroppedControlModel(id: string, parentId: string): ControlModel {
        let control;
        if (this.idIsForRecentControl(id)) {
            var toBeClonedControl = this.fetchControlModel(id);
            control = this.utils.deepClone(toBeClonedControl);
            control.ControlId += (++this.newlyAddedSuffix);
            this.controlModels.push(control);
        } else {
            control = this.fetchControlModel(id);
        }
        if (!control) {
            throw new Error("Dropped control doesn't exist!");
        }

        control.ParentControlId = parentId;
        if (this.controlIsInGroup(control, 'ContainerItem') && parentId) {
            var parentControl = this.fetchControlModel(parentId);
            if (this.controlIsInGroup(parentControl, 'ContainerGroup')) {
                control.ControlTypeId = parentControl.ControlTypeId + 'Item';
            }
        }

        return control;
    }
    public controlIsInGroup(controlModel: ControlModel, group: string): boolean {
        var controlType = this.getControlTypes().find(item => controlModel.ControlTypeId === item.Id);
        if (controlType === undefined) {
            throw new Error(`controlModel had an invalid type ${controlModel.ControlTypeId}`);
        }
        return (controlType.ControlGroups || []).includes(group);
    };

    public propertyIsRelevant(control: ControlModel, propertyId: string): boolean {
        return this.propertyTypes[propertyId].controlGroups.some((item) => {
            return (control.ControlGroups && control.ControlGroups.indexOf(item) !== -1)
                || 
                item === 'All'
                ||
                (this.isFilter && item === 'Filter')
                ||
                (this.isColumnSettings && item === 'Column');
        });
    };
    public getPropertyValueType(propertyId): PropertyValueType {
        return propertyId ?
            (this.propertyTypes[propertyId].type || 'String')
            : 'String'; // todo enum or string type
    };
    public fetchControlModel(controlId: string): ControlModel {
        const controls = this.controlModels.filter(c => c.ControlId === controlId);
        if (controls.length === 1) {
            return controls[0];
        }
        else {
            console.log(controls);
            console.log(controlId);
            throw new Error('No or more than one control found in models!!!');
        }
    };

    private idIsForRecentControl(id: string): boolean { // todo possible to move into id logics
        return id.includes('recently-added-control') && !this.utils.isNumeric(id[id.length - 1]);
    }
    private getPropertyTypes(): { [key: string]: PropertyType } { // todo should go into providers
        const propertyTypes = (window as any).propertyTypes;
        if (propertyTypes === undefined)
            throw new Error("propertyTypes not provided.");
        return propertyTypes;
    }
    public updateFamilyIfNeeded(control: ControlModel, newControlType: string) {  // todo needs structural refactoring          
        if (newControlType === 'FieldSet') {
            const children = this.getChildren(control, child => this.controlIsInGroup(child, 'ContainerItem'));
            for (var i = 0; i < children.length; i++) {
                children[i].ControlTypeId = 'FieldSet';
            }

            const parent = this.getParent(control);
            if (this.controlIsInGroup(parent, 'ContainerGroup')) {
                parent.ControlTypeId = 'FieldSet';
                var siblings = this.getSiblings(control, sibling =>
                    this.controlIsInGroup(sibling, 'ContainerItem')
                );
                for (var j = 0; j < siblings.length; j++) {
                    siblings[j].ControlTypeId = 'FieldSet';
                }
            }
            return;
        }

        if (this.controlIsInGroup(control, 'ContainerItem')) {
            var parent = this.getParent(control);
            if (!this.controlIsInGroup(parent, 'ContainerGroup'))
                throw "Transforming to containerItem without a parent.";
            parent.ControlTypeId =
                newControlType.substring(0, newControlType.indexOf('Item')); //todo is this convention enough?
            var siblings = this.getSiblings(control, sibling =>
                this.controlIsInGroup(sibling, 'ContainerItem')
            );
            for (var j = 0; j < siblings.length; j++) {
                siblings[j].ControlTypeId = newControlType;
            }
        }

        if (this.controlIsInGroup(control, 'ContainerGroup')) {
            const children = this.getChildren(control, child =>
                this.controlIsInGroup(child, 'ContainerItem')
            );
            for (var i = 0; i < children.length; i++) {
                children[i].ControlTypeId = newControlType + 'Item';
            }
        }
    };
    private controlIsInput(control): boolean {
        return this.controlIsInGroup(control, 'Input'); //todo
    };

    private getChildren(control: ControlModel, filterFunction: (cm: ControlModel) => boolean): ControlModel[] {
        return this.controlModels.filter(controlModel => {
            if (control.ControlId !== controlModel.ParentControlId)
                return false;
            if (filterFunction)
                return filterFunction(controlModel);
            return true;
        });
    };

    private getSiblings(control: ControlModel, filterFunction: (cm: ControlModel) => boolean): ControlModel[] {
        return this.controlModels.filter(controlModel => {
            if (controlModel.ParentControlId !== control.ParentControlId)
                return false;
            if (filterFunction)
                return filterFunction(controlModel);
            return true;
        });
    };

    private getParent(control: ControlModel): ControlModel {
        for (const controlModel of this.controlModels) {
            if (controlModel.ControlId === control.ParentControlId)
                return controlModel;
        }
        return null;
    };
}