import { DragAndDropManager } from './form-interactions/drag-n-drop-manager';
import { ControlModel } from './models/form-models/control-model';
import { FormDomManager } from './form-interactions/form-dom-manager';
import { ControlModelsManager } from './logic/control-models-manager';
import { EntitiesModelProvider } from './providers/entities-model-provider';
import { PropertyType } from './models/form-models/property-type';
import { ControlType } from './models/form-models/control-type';
import { UtilityByJquery } from './utils/utility';
import { PropertiesComponent } from './components/properties-component';
import { CutAndPasteManager } from './form-interactions/cut-n-paste-manager';
import { Property } from '../dist/models/form-models/property-model';
class FormDesigner {
    private domManager: FormDomManager;
    private modelManager: ControlModelsManager;
    private entitiesModelProvider: EntitiesModelProvider;
    constructor(private $: JQueryStatic, rootUrl: string, controls: ControlModel[],
        propertyTypes: PropertyType[], getControlTypes: () => ControlType[],
        isFilter: boolean,
        isColumnSettings: boolean = false) {
        // todo instantiating and injecting dependencies and setting up components
        this.entitiesModelProvider = new EntitiesModelProvider($, rootUrl);
        this.modelManager = new ControlModelsManager(controls, propertyTypes,
            getControlTypes, new UtilityByJquery($), isFilter, isColumnSettings);
        this.domManager = new FormDomManager($, this.modelManager, this.showProperties);
        new DragAndDropManager($, this.domManager, this.modelManager);
        new CutAndPasteManager(this.$, this.modelManager);
    }

    public getSelectedControls(): ControlModel[] {
        return this.domManager.getSelectedControlsIds()
            .map(id => this.modelManager.fetchControlModel(id));
    }

    // Seems weird and it is! But currently, index column-settings uses it.
    public getProperties(controlId: string): Property[] {
        return this.modelManager.fetchControlModel(controlId).Properties;
    }

    private showProperties = (controlId: string, $target: JQuery<HTMLElement>) => {
        new PropertiesComponent(this.modelManager.fetchControlModel(controlId),
            this.modelManager, this.domManager, this.$, this.entitiesModelProvider, 
            $target).render();
    }
}
(<any>window).FormDesigner = FormDesigner; // todo more sane way!