import { ControlModel } from "../models/form-models/control-model";
import { SystemLinkAddress } from '../models/form-models/system-link-address-model';
import { SubTable } from '../models/form-models/sub-table-model';
import { ControlModelsManager } from '../logic/control-models-manager';
import { EntitiesModelProvider } from "../providers/entities-model-provider";
import { ControlType } from '../models/form-models/control-type';
import { FormDomManager } from '../form-interactions/form-dom-manager';
import { Property } from "../models/form-models/property-model";
import { PropertyValueType } from "../models/form-models/property-value-type";

export class PropertiesComponent {
    private readonly renderedPropertiesIndices: Array<number> = [];
    get subTable(): SubTable {
        if (!this.control.SubTable)
            this.control.SubTable = <SubTable>{};
        return this.control.SubTable;
    };
    get systemLinkAddress(): SystemLinkAddress {
        if (!this.control.SystemLinkAddress)
            this.control.SystemLinkAddress = <SystemLinkAddress>{};
        return this.control.SystemLinkAddress;
    };
    constructor(private readonly control: ControlModel,
        private readonly modelsManager: ControlModelsManager,
        private readonly formDomManager: FormDomManager,
        private readonly $: JQueryStatic,
        private readonly entitiesProvider: EntitiesModelProvider,
        private readonly $form: JQuery<HTMLElement>) {
    }

    public render(): void {
        this.$form.html('');
        this.initialize();
        this.renderPropertiesForm();
    }

    private renderControlId(): void {
        const $div = this.$(
            `<div class="form-group col-sm-12">
                <label for="input-control-id">شناسه</label>
            </div>`);
        const $input = this.$('<input/>', {
            "dir": "ltr",
            "type": "text",
            "class": "form-control",
            "id": "input-control-id",
            "name": "formItem.ControlId",
            "value": this.control.ControlId,
            "on": {
                "change": (event: JQueryEventObject) => {
                    this.controlIdChanged(event.target);
                }
            }
        });
        $div.append($input);
        this.$form.append($div);
    }
    private renderLabel() {
        const $div = this.$(
            `<div class="form-group col-sm-6">
                <label for="input-label">عنوان</label>
            </div>`);
        const $input = this.$('<input/>', {
            "dir": "ltr",
            "type": "text",
            "class": "form-control",
            "id": "input-label",
            "name": "formItem.Label",
            "value": this.control.Label,
            "on": {
                "change": (event: JQueryEventObject) => {
                    this.labelChanged(event.target);
                }
            }
        });
        $div.append($input); // todo does it add to label or div?!!
        this.$form.append($div);
    }

    private getPropertyValueInput(property: Property, valueType: PropertyValueType, idx: number): JQuery<HTMLElement> {
        const valueInputAttributes = {
            'type': '',
            "on": {
                "change": (event: JQueryEventObject) => {
                    this.propertyValueChanged(event.target);
                }
            },
            'class': "form-control",
            style: "direction: ltr;",
            placeholder: "مقدار",
            id: `property-value-${idx}`,
            value: property.Value,
            'data-property-type': `${valueType}`,
            'name': `formItem.Properties[${idx}].Value`
        };
        switch (valueType) {
            case 'String':
                valueInputAttributes.type = "text";
                break;
            case 'Int':
                valueInputAttributes.type = "number";
                break;
            case 'Double':
                valueInputAttributes.type = "number";
                valueInputAttributes['step'] = 'any';
                break;
            case 'Color':
                valueInputAttributes.type = "color";
                break;
            case 'Boolean':
                valueInputAttributes.type = "checkbox";
                valueInputAttributes.class = "";
                delete valueInputAttributes.value;
                if (property.Value) {
                    valueInputAttributes['checked'] = 'checked';
                }
                break;
            case 'List':
                valueInputAttributes.type = "text";
                //todo
                break;
            case 'ContextualStyle':
                valueInputAttributes.style = '';
                const selectedStyle = this.contextualStyleOptions.find(s => s.value === property.Value);
                if (selectedStyle) {
                    valueInputAttributes.class += ` ${selectedStyle.class}`;
                }
                break;
            default:
                throw "InvalidPropertyValueType";
        }
        let $valueInput: JQuery<HTMLElement>;
        if (valueType === 'ContextualStyle') {
            $valueInput = this.$('<select/>', valueInputAttributes);
            const $styleOptions = this.getStyleOptions(property);
            $valueInput.append($styleOptions);
        }
        else {
            $valueInput = this.$('<input/>', valueInputAttributes);
        }
        return $valueInput;
    }

    private contextualStyleOptions = [
        {
            text: 'اصلی',
            value: 'Primary',
            class: 'bg-primary text-white'
        },
        {
            text: 'فرعی',
            value: 'Secondary',
            'class': 'bg-secondary text-white'
        },
        {
            text: 'موفق',
            value: 'Success',
            'class': 'bg-success text-white'
        },
        {
            text: 'هشدار',
            value: 'Warning',
            'class': 'bg-warning'
        },
        {
            text: 'خطر',
            value: 'Danger',
            'class': 'bg-danger text-white'
        },
        {
            text: 'روشن',
            value: 'Light',
            'class': 'bg-light text-dark'
        },
        {
            text: 'تاریک',
            value: 'Dark',
            'class': 'bg-dark text-white'
        }
    ];
    private getStyleOptions(property: Property) {

        const $styleOptions = this.contextualStyleOptions.map(cStyle => this.$('<option/>', {
            value: cStyle.value,
            selected: property.Value === cStyle.value,
            text: cStyle.text,
            'class': cStyle.class
        }));
        return $styleOptions;
    }

    private propertyTypeChanged(el: Element): void {
        const propertyIdx = this.$(el).attr('property-idx');
        const propertyId = this.$(el).val();
        const $propertyValueInput = this.$('#property-value-' + propertyIdx);
        const property = this.control.Properties[propertyIdx];
        property.PropertyId = propertyId;

        const previousInputType = $propertyValueInput.attr('data-property-type');
        if (previousInputType === 'Boolean' && $propertyValueInput.siblings('.toggle-group').length)
            $propertyValueInput.bootstrapToggle('destroy');

        const valueType = this.modelsManager.getPropertyValueType(propertyId);

        const $wrapper = $propertyValueInput.parent();
        $wrapper.html('');
        const $newInput = this.getPropertyValueInput(property, valueType, Number(propertyIdx));
        $wrapper.append($newInput);

        if (valueType === 'Boolean') {
            this.instantiateToggleFor($newInput);
        }
    }
    private instantiateToggleFor($input: JQuery<HTMLElement>) {
        $input.bootstrapToggle({
            on: 'بله',
            off: 'خیر',
            onstyle: 'success',
            width: "100%"
        });
    }

    private renderPropertyValue($parent: JQuery<HTMLElement>, idx: number): void {
        const $valueDiv = this.$('<div class="col-sm-5 little-padding"></div>');
        const property = this.control.Properties[idx];
        const valueType = this.modelsManager.getPropertyValueType(property.PropertyId);
        const $valueInput = this.getPropertyValueInput(property, valueType, idx);
        $valueDiv.append($valueInput).appendTo($parent);
        this.$form.find('#properties-div').append($parent);
        if (valueType === 'Boolean') {
            this.instantiateToggleFor(this.$('#property-value-' + idx));
        }

    }
    private renderOtherProperty(propertyIdx) {
        const $parentDiv = this.$('<div/>', {
            "class": "form-group row container-fluid"
        });
        const $removeDiv = this.$('<div/>', {
            "class": "col-sm-1"
        });
        const $removeButton = this.$('<i/>', {
            "class": "fa fa-trash mouse-pointer",
            'id': `remove-property-id-${propertyIdx}`,
            'click': (event: JQueryEventObject) => {
                this.removeProperty(event.target, propertyIdx);
            },
            'style': "font-size: 1.2em; color: rgb(197, 0, 0); text-align: center; margin-top: 10px; float: left;"
        });
        $removeDiv.append($removeButton)
            .appendTo($parentDiv);
        const $typeDiv = this.$('<div/>', {
            "class": "col-sm-5"
        });
        const $typeSelect = this.$('<select/>', {
            on: {
                change: (event: JQueryEventObject) => {
                    this.propertyTypeChanged(event.target);
                },
            },
            'class': "form-control property-type",
            id: `property-id-${propertyIdx}`,
            name: `formItem.Properties[${propertyIdx}].PropertyId`,
            'property-idx': propertyIdx
        });
        $typeSelect.append(this.$('<option/>'));
        const propertyTypes = this.modelsManager.getRelevantPropertyTypes(this.control);
        const typeOptions = Object.keys(propertyTypes).map(propertyId => this.$('<option/>', {
            value: propertyId,
            selected: propertyId === this.control.Properties[propertyIdx].PropertyId,
            text: propertyTypes[propertyId].title || propertyId
        }));
        $typeSelect.append(typeOptions).appendTo($typeDiv);
        $parentDiv.append($typeDiv);
        this.renderPropertyValue($parentDiv, propertyIdx);
    }
    private renderOtherProperties() {
        this.$form.append(this.otherPropertiesFieldset());
        if (!this.control.Properties)
            return;
        for (let index = 0; index < this.control.Properties.length; index++) {
            if (this.renderedPropertiesIndices.includes(index))
                continue;
            this.renderedPropertiesIndices.push(index);
            this.renderOtherProperty(index);
        }
    }
    private otherPropertiesFieldset(): JQuery<HTMLElement> {
        const fieldSet = this.$('<fieldset/>', {
            "class": "col-lg-12"
        });
        fieldSet.append(this.otherPropertiesLegend());
        fieldSet.append(this.otherPropertiesDiv());
        return fieldSet;
    }
    private otherPropertiesLegend(): JQuery<HTMLElement> {
        const legend = this.$('<legend/>', {
            text: "سایر ویژگی‌ها"
        });
        const addPropertyButton = this.$('<i/>', {
            id: "add-property",
            click: this.addProperty,
            "class": "fa fa-plus-circle mouse-pointer mr-1",
            style: "color: rgb(122, 233, 71);"
        });
        legend.append(addPropertyButton)
        return legend;
    }
    private otherPropertiesDiv(): JQuery<HTMLElement> {
        return this.$(
            `<div class="row" id="properties-div">
                <div class="col-sm-5" style="margin-right:9%">نوع ویژگی</div>
                <div class="col-sm-5 little-padding">مقدار</div>
            </div>`);
    }

    private renderTransformationOptions() {
        const div = this.$('<div/>', {
            class: "col-sm-6"
        });
        const label = this.$('<label/>', {
            text: "نوع کنترل",
            for: "control-transformation"
        });
        const selectBox = this.$('<select/>', {
            "id": "control-transformation",
            "class": "form-control",
            "on": {
                "change": (event: JQueryEventObject) => {
                    this.controlTypeChanged(event.target)
                }
            }
        });
        selectBox.append(this.alternativeOptions(this.modelsManager.obtainAlternativeControls(this.control)));
        div.append(label);
        div.append(selectBox);
        this.$form.append(div);
    }
    private alternativeOptions(alternativeControls: ControlType[]): JQuery<HTMLElement>[] {
        return alternativeControls.map(ac => this.$("<option/>", {
            value: ac.Id,
            selected: ac.Id === this.control.ControlTypeId,
            text: ac.Name
        }));
    }
    private getNamespaceSelectBox(selectedValue: string): JQuery<HTMLElement> {
        const selectBox = this.$('<select/>', {
            "id": "table-namespace-id",
            "class": "form-control",
            "data-table-property": "NamespaceId",
            "on": {
                "change": (event: JQueryEventObject) => {
                    this.tablePropertyChanged(event.target)
                }
            }
        });
        const options = this.entitiesProvider
            .getNamespacesList()
            .map(namespace  => this.$('<option/>', {
                selected: namespace.id === selectedValue,
                value: namespace.id,
                title: namespace.id,
                text: namespace.name
            }));
        selectBox.append(options);
        return selectBox;
    }
    private getEntitySelectBox(namespaceId: string, selectedValue: string): JQuery<HTMLElement> {
        const selectBox = this.$('<select/>', {
            "class": "form-control",
            "data-table-property": "EntityId",
            "id": "table-entity-id",
            "on": {
                "change": (event: JQueryEventObject) => {
                    this.tablePropertyChanged(event.target)
                }
            }
        });
        const options = this.entitiesProvider
            .getEntitiesOfNamespace(namespaceId)
            .map(entity => this.$('<option/>', {
                selected: entity.id === selectedValue,
                value: entity.id,
                title: entity.id,
                text: `${entity.name} - ${entity.id}`
            }));
        selectBox.append(options);
        return selectBox;
    } //todo call it when namespace  changed
    private tablePropertyChanged(el: Element) {
        const $el = this.$(el);
        this.subTable[$el.data('table-property')] = $el.val();
        if ($el.data('table-property') === 'NamespaceId') {
            this.$('#table-entity-id').select2('destroy');
            this.$('#table-entity-id').replaceWith(this.getEntitySelectBox($el.val() as string, ''));
            this.$('#table-entity-id').select2({ dropdownParent: this.$("#propertiesModal") });
        }
    }
    private renderTableProperties() {
        const $fieldset = this.fieldset('ویژگی‌های جدول');
        const $namespace = this.createLgDiv(6)
            .append(this.inputLabel('table-namespace-id', 'فضای نامی موجودیت جدول'))// todo append to parent or lately created element?
            .append(this.getNamespaceSelectBox(this.subTable.NamespaceId));
        const $entity = this.createLgDiv(6)
            .append(this.inputLabel('table-entity-id', 'موجودیت جدول'))// todo append to parent or lately created element?
            .append(this.getEntitySelectBox(this.subTable.NamespaceId, this.subTable.EntityId));
        const $tableAssociation = this.createLgDiv(6)
            .append(this.inputLabel('table-tableassociation-id', 'فیلد ارتباط در موجودیت جدول'))// todo append to parent or lately created element?
            .append(this.subTableInput(this.subTable.TableAssociationId, 'TableAssociationId', 'table-tableassociation-id'));
        const $tableFieldAssociation = this.createLgDiv(6)
            .append(this.inputLabel('table-association-id', 'فیلد ارتباط در موجودیت فرم'))// todo append to parent or lately created element?
            .append(this.subTableInput(this.subTable.AssociationId, 'AssociationId', 'table-association-id', 'Id'));
        const $subject = this.createLgDiv(6)
            .append(this.inputLabel('table-subject-id', 'موضوع فرم جدول'))// todo append to parent or lately created element?
            .append(this.subTableInput(this.subTable.IndexFormSubjectId, 'IndexFormSubjectId', 'table-subject-id'));

        $fieldset.append($namespace)
            .append($entity)
            .append($tableAssociation)
            .append($tableFieldAssociation)
            .append($subject)
            .appendTo(this.$form);
        this.$('#table-entity-id').select2({ dropdownParent: this.$("#propertiesModal") });
    }
    private subTableInput(value: string, propertyName: string, id: string, placeholder?: string): JQuery<HTMLElement> {
        return this.$('<input/>', {
            'value': value || '',
            'class': "form-control",
            'type': 'text',
            'data-table-property': propertyName,
            placeholder,
            id,
            on: {
                change: (event: JQueryEventObject) => {
                    this.tablePropertyChanged(event.target);
                }
            }
        });
    }
    private fieldset(legendTitle: string): JQuery<HTMLElement> {
        return this.$(
            `<fieldset class="col-lg-12 row m-0">
                <legend>${legendTitle}</legend>
            </fieldset>`
        );
    }
    private inputLabel(forInput: string, text: string): JQuery<HTMLElement> {
        return this.$('<label/>', {
            for: forInput,
            text
        });
    }
    private createLgDiv(col: number): JQuery<HTMLElement> {
        return this.$('<div/>', {
            "class": `col-lg-${col}`
        });
    }
    private renderSystemPageLinkProperties() {
        const $fieldset = this.fieldset('ویژگی‌های لینک به فرم');
        const $linkNamespace = this.systemPageLinkProperty('link-namespace-id',
            'فضای نامی', this.systemLinkAddress.NamespaceId, 'NamespaceId');
        const $linkEntity = this.systemPageLinkProperty('link-entity-id',
            'شناسه‌ی موجودیت', this.systemLinkAddress.EntityId, 'EntityId');
        const $linkForm = this.systemPageLinkProperty('link-form-id',
            'شناسه‌ی فرم', this.systemLinkAddress.FormId, 'FormId');
        $fieldset.append($linkNamespace)
            .append($linkEntity)
            .append($linkForm);
        this.$form.append($fieldset);
    }
    private systemPageLinkProperty(id: string, name: string, value: string, propertyName: string): JQuery<HTMLElement> {
        return this.createLgDiv(6)
            .append(this.inputLabel(id, name))
            .append(this.$('<input/>', {
                value: value || '',
                class: 'form-control',
                'data-link-property': propertyName,
                id,
                'type': "text",
                on: {
                    change: (event: JQueryEventObject) => {
                        this.systemPageLinkPropertyChanged(event.target);
                    }
                }
            }));
    }
    private renderSpecificProperties() {
        if (this.modelsManager.controlIsInGroup(this.control, 'Table'))
            this.renderTableProperties();
        if (this.control.ControlTypeId === 'SystemPageLink')
            this.renderSystemPageLinkProperties();
    }
    /**
     * based on control group, render appropriate form
        render additional properties
        change detection mechanism to reflect to the control object
     */
    private renderPropertiesForm() {
        this.renderControlId();
        this.renderLabel();
        this.renderTransformationOptions();
        this.renderSpecificProperties();
        this.renderOtherProperties();
    }
    private addProperty = () => {
        if (this.control.Properties === null)
            this.control.Properties = [];
        var arrayLength = this.control.Properties.length;
        this.control.Properties.push({ PropertyId: 'None', Value: '' });//todo
        this.renderedPropertiesIndices.push(arrayLength);
        this.renderOtherProperty(arrayLength);
    }
    private removeProperty(el, idx) {
        this.control.Properties.splice(idx, 1);
        this.renderedPropertiesIndices.splice(this.renderedPropertiesIndices.indexOf(idx), 1);
        this.$(el).closest('.form-group').remove();
    }
    private initialize() {
        this.renderedPropertiesIndices.length = 0; // todo
    }
    private controlTypeChanged(el: Element): void {
        const newValue = $(el).val() as string;
        if (newValue)
            this.control.ControlTypeId = newValue;
        this.modelsManager.updateFamilyIfNeeded(this.control, newValue);
    }
    private controlIdChanged(el: Element): void {
        this.formDomManager.reflectIdChange(this.control.ControlId, this.$(el).val());
        this.control.ControlId = this.$(el).val() as string;
    }
    private labelChanged(el: Element): void {
        this.control.Label = this.$(el).val() as string;
        this.formDomManager.reflectLabelChange(this.control);
    }
    private propertyValueChanged(el: Element): void {
        var $el = $(el);
        var propertyValue = $el.val();

        if ($el.attr('data-property-type') === 'Boolean')
            propertyValue = $el.prop('checked');
        var propertyIdx = el.id.split('-')[2];
        this.control.Properties[propertyIdx].Value = propertyValue;
    }
    private systemPageLinkPropertyChanged(el: Element): void {
        var $el = $(el);
        this.systemLinkAddress[$el.data('link-property')] = $el.val();
    }
}