import { ControlModelsManager } from '../logic/control-models-manager';
export class CutAndPasteManager {
    private readonly cutSelector = '.cut-icon';
    private readonly pasteSelector = '.paste-icon';
    private readonly cancelSelector = '#cancel-cut';
    constructor(private $: JQueryStatic,
        private modelManager: ControlModelsManager) {
        this.$(this.cutSelector).on('click', this.cut);
        this.$(this.pasteSelector).on('click', this.paste);
        this.$(this.cancelSelector).on('click', this.cancel);
    }

    private cut = (event: JQueryEventObject) => {
        const $control = this.$(event.target).closest('[data-id]');
        $control.addClass('hidden')
            .addClass('cutted');

        this.$(this.cutSelector).addClass('hidden');
        this.$(this.pasteSelector).removeClass('hidden');
        // todo only paste-icon of the items which can be pasted in, should be shown
        this.$(this.cancelSelector).removeClass('hidden');
    }
    private paste = (event: JQueryEventObject) => {
        let $containerControl = this.$(event.target).closest('[data-id]');
        if (!$containerControl.length)
            $containerControl = this.$('#main-part');
        const $container = $containerControl.is('.sortable-container') ?
            $containerControl :
            $containerControl.find('.sortable-container').first();
        $container.prepend(this.$('.cutted'));
        this.modelManager.grabDroppedControlModel(this.$('.cutted').data('id'),
            $containerControl.data('id'));
        this.reset();
    }
    private cancel = (event: JQueryEventObject) => {
        this.reset();
    }
    private reset() {
        this.$('.cutted')
            .removeClass('hidden')
            .removeClass('cutted');

        this.$(this.cutSelector).removeClass('hidden');
        this.$(this.pasteSelector).addClass('hidden');
        this.$(this.cancelSelector).addClass('hidden');
    }
}