import { ControlModel } from '../models/form-models/control-model';
import { ControlModelsManager } from '../logic/control-models-manager';
// todo maybe removing its dependency on modelManager and making a bridge between them
export class FormDomManager {
    private _propertiesFormTarget: JQuery<HTMLElement>;
    private get propertiesFormTarget(): JQuery<HTMLElement> {
        if (!this._propertiesFormTarget ||
            this._propertiesFormTarget.length === 0) {
            this._propertiesFormTarget = $('#propertiesModal .modal-body > .row');
        }
        return this._propertiesFormTarget;
    };
    constructor(private $: JQueryStatic,
        private modelManager: ControlModelsManager,
        private showProperties: (controlId: string, $target: JQuery<HTMLElement>) => void) {
        this.setEventHandlers();
    }

    public getSelectedControlsIds(): string[] {
        const ids = [];
        this.$('#main-part [data-id]').each((idx, item) => {
            ids.push(this.$(item).data('id'));
        });
        return ids;
    }
    public getParentId($item: JQuery<HTMLElement>): string {
        const daddy = $item.parents('[data-id]')[0];
        return daddy ? $(daddy).data('id') : null;
    }
    public setControlId($item: JQuery<HTMLElement>, id: string): void {
        $item.data('id', id);
        $item.attr('data-id', id);
    }

    public reflectLabelChange(control: ControlModel): void {
        if (this.modelManager.controlIsInGroup(control, 'ContainerItem') ||
            this.modelManager.controlIsInGroup(control, 'ContainerGroup'))
            this.$('div[data-id=' + control.ControlId + '] legend').first().text(control.Label);
        else
            //                if (controlIsInput())
            this.$('div[data-id=' + control.ControlId + '] label').text(control.Label + ':');
    };

    public reflectIdChange(prevId, newId): void {
        this.setControlId(this.$('[data-id=' + prevId + ']'), newId);
    };

    public getControlId($item: JQuery<HTMLElement>): string {
        return $item.data('id');
    }

    private setEventHandlers(): void {
        this.$('.remove-icon').on('click',
            (event: JQueryEventObject) => {
                const $element = $(event.target);
                const removeTargetId = $element.attr('remove-target');
                const $removeTarget = $element.closest("[data-id^='" + removeTargetId + "']");
                if (removeTargetId.startsWith('recently-added-control'))
                    $removeTarget.remove();
                else
                    $removeTarget.prependTo('#form-builder-toolbox-fields'); //todo container controls shouldn't move, but their fields should
            });
        this.$('.properties-icon').on('click',
            (event: JQueryEventObject) => {
                const id = $(event.target).closest('[data-id]').data('id');
                this.showProperties(id, this.propertiesFormTarget);
                this.$('#propertiesModal').modal('show');
            });
    }
}