import { Namespace } from "../models/entities-models/namespace";
import { Entity } from "../models/entities-models/entity";
import { ControlType } from '../models/form-models/control-type';

export class EntitiesModelProvider {
    private namespacesList: Namespace[];
    private entitiesList: Entity[];
    private controlTypes: ControlType[];
    constructor(private $: JQueryStatic, rootUrl: string) {
        this.$.get(rootUrl + 'MetaDesign/App/api/namespaces')
            .then((res) => {
                this.namespacesList = res
            }); //todo not robust
        this.$.get(rootUrl + 'MetaDesign/App/api/entities')
            .then((res) => {
                this.entitiesList = res
            }); //todo not robust(1. asynch 2. exception handling)
    }

    public getNamespacesList(): Namespace[] {
        return this.namespacesList;
    }
    public getEntitiesOfNamespace(namespaceId: string): any {
        return this.entitiesList.filter(entity => entity.namespaceId === namespaceId);
    }    
    public getEntitiesList(): Entity[] {
        return this.entitiesList;
    }
}